() => {
  const aside = document.querySelector('aside, [role="complementary"]');
  if (!aside) return 'no aside';
  const rect = aside.getBoundingClientRect();
  const buttons = [...aside.querySelectorAll('button')].map((b, i) => ({
    i,
    title: b.getAttribute('title'),
    aria: b.getAttribute('aria-label'),
    text: (b.innerText || '').trim().slice(0, 20),
    y: Math.round(b.getBoundingClientRect().y)
  }));
  return { width: rect.width, buttons };
}

() => {
  const aside = document.querySelector('aside, [role="complementary"]');
  const buttons = [...aside.querySelectorAll('button')];
  return buttons.map((b, i) => ({
    i,
    svg: b.querySelector('svg') ? (b.querySelector('svg').getAttribute('class') || 'svg') : 'none',
    cls: (b.className || '').slice(0, 80),
    html: b.innerHTML.slice(0, 120)
  }));
}
